# A failed action's card says only that it failed. Run from the worktree root.
import sys


def edit(path, pairs):
    s = open(path).read()
    for old, new in pairs:
        if s.count(old) != 1:
            sys.exit(f'{path}: expected 1, found {s.count(old)}: {old[:120]!r}')
        s = s.replace(old, new)
    open(path, 'w').write(s)


root = 'src/slic3r/GUI/JusPrin/'
edit(root + 'AgentUI/src/components/ToolActivityCard.tsx', [
    ('''// A refusal whose message is written for the model can carry the card's own
// line in its details as "shown".
function shownLine(activity: ToolActivityInfo): string | undefined {
  const shown = activity.error?.details?.shown;
  return typeof shown === 'string' && shown ? shown : undefined;
}

''', ''),
    ('''// One native tool action, rendered from the authoritative activity record
// the host pushes. The native coordinator owns the state machine.
''', '''// One native tool action, rendered from the authoritative activity record
// the host pushes. The native coordinator owns the state machine. A failed
// action's error is the AI model's to read: the card says only that it
// failed, or that it did not run because the project changed first.
'''),
    ('''          : shownLine(activity) ?? activity.error?.message ?? stateLabels.failed''',
     '''          : stateLabels.failed'''),
])
edit(root + 'AgentUI/src/components/ProposalCard.tsx', [
    ('''import { ToolActivityInfo } from '../bridge/protocol';''',
     '''import { isStale, ToolActivityInfo } from '../bridge/protocol';'''),
    ('''  const failure = save?.state === 'failed' ? save.error?.message : undefined;''',
     '''  // The save's error is the AI model's to read; the card says only what
  // happened, as an action's card does.
  const failure = save?.state === 'failed'
    ? isStale(save) ? t`The project changed before this could run. Ask AI again.` : t`The action failed.`
    : undefined;'''),
])
edit(root + 'PrinterSetup/PrinterConversation.cpp', [
    ('''    return ToolError{"unknown_device", lead + "Pass the deviceId of one of these printers in LAN mode: " + listed + "." + tail,
                     json{{"shown", "Pick one of these printers to connect."}}.dump()};''',
     '''    return ToolError{"unknown_device", lead + "Pass the deviceId of one of these printers in LAN mode: " + listed + "." + tail};'''),
])
edit(root + 'PrinterSetup/PrinterConversation.hpp', [
    ('''    // after `lead`. When it lists printers to pick from, its details carry
    // the card's own line, "shown", since the message is the model's.
''', '''    // after `lead`.
'''),
])
print('cards applied')

# The plates pane reports an action that fails. Run from the worktree root.
import sys

path = 'src/slic3r/GUI/JusPrin/Shell/LeftPane.cpp'
s = open(path).read()


def rep(old, new, count=1):
    global s
    found = s.count(old)
    if found != count:
        sys.exit(f'expected {count}, found {found}: {old[:120]!r}')
    s = s.replace(old, new)


rep('''    Bind(wxEVT_LEFT_DOWN, &LeftPane::on_left_down, this);''',
    '''    // A click or a key runs the pane's commands, and a command that fails
    // goes up to here, to be reported.
    Bind(wxEVT_LEFT_DOWN, reported("using the plates pane", [this](wxMouseEvent& event) { on_left_down(event); }));''')
rep('''    Bind(wxEVT_KEY_DOWN, &LeftPane::on_key_down, this);''',
    '''    Bind(wxEVT_KEY_DOWN, reported("using the plates pane", [this](wxKeyEvent& event) { on_key_down(event); }));''')

rep('''void LeftPane::run_command(const CommandResult& result, const char* what) const
{
    // Choosing what is already chosen is not an error.
    if (result.succeeded() || result.error == WorkspaceError::NoChange)
        return;
    BOOST_LOG_TRIVIAL(error) << "Plates pane: " << what << " failed: " << result.message;
    OrcaMessages::show_own_message(nullptr, wxString::FromUTF8(result.message), _L("Couldn't do that"));
}''', '''void LeftPane::run_command(const CommandResult& result, const char* what) const
{
    // Choosing what is already chosen is not an error.
    if (result.succeeded() || result.error == WorkspaceError::NoChange)
        return;
    // Nobody decided what the person is told: the failure goes up to the
    // handler the pane's click, key or menu row runs under, which reports it.
    throw RuntimeError(std::string("Plates pane: ") + what + " failed: " + result.message);
}

void LeftPane::show_refusal(const CommandResult& result, WorkspaceError refusal, const char* what) const
{
    if (result.error != refusal)
        return run_command(result, what);
    BOOST_LOG_TRIVIAL(error) << "Plates pane: " << what << " failed: " << result.message;
    OrcaMessages::show_own_message(nullptr, wxString::FromUTF8(result.message), _L("Couldn't do that"));
}''')

# The two refusals a person may be able to act on keep their dialog until
# Kenneth decides what they say.
rep('''    run_command(m_workspace.add_plate(), "add plate");''',
    '''    show_refusal(m_workspace.add_plate(), WorkspaceError::Refused, "add plate");''')
rep('''        run_command(m_workspace.rename_object(object, std::string(dialog.GetValue().ToUTF8())), "rename object");''',
    '''        show_refusal(m_workspace.rename_object(object, std::string(dialog.GetValue().ToUTF8())), WorkspaceError::InvalidArgument,
                     "rename object");''')
if '#include "libslic3r/Exception.hpp"' not in s:
    rep('#include "slic3r/GUI/GUI_App.hpp"\n', '#include "slic3r/GUI/GUI_App.hpp"\n#include "libslic3r/Exception.hpp"\n')
open(path, 'w').write(s)

path = 'src/slic3r/GUI/JusPrin/Shell/LeftPane.hpp'
s = open(path).read()
rep('''    void       run_command(const Workspace::CommandResult& result, const char* what) const;''',
    '''    void       run_command(const Workspace::CommandResult& result, const char* what) const;
    // run_command, except that the one refusal named keeps its own dialog:
    // "No more plates can be added" and "Object name cannot be empty", which
    // wait for Kenneth's decision on what they tell the person.
    void       show_refusal(const Workspace::CommandResult& result, Workspace::WorkspaceError refusal, const char* what) const;''')
open(path, 'w').write(s)
print('left pane applied')

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

